// Generated by `monoceros apply` from the agent-roles feature. Edits here are
// overwritten on the next apply.
//
// The agent-roles guard for OpenCode. Claude Code and Copilot run guard.mjs as
// a PreToolUse hook; OpenCode has no hook command, but a plugin can refuse a
// tool call by throwing in `tool.execute.before`. This plugin hands the call to
// the same guard.mjs, so all three agents are held to one set of rules.
//
// `tool.execute.before` does not say which agent made the call, so the plugin
// learns it from `chat.params`, which runs before every model call with the
// session and its agent. A session's tool calls come out of its model calls,
// so the agent is always known by the time one of them arrives. Sessions of
// any other agent (`build`, `plan`, the title agent) are left alone.

import { spawnSync } from 'node:child_process';

const GUARD = '{{GUARD}}';
const PREFIX = 'agent-roles-';

export const AgentRolesGuard = async ({ directory }) => {
  const agents = new Map();
  return {
    'chat.params': async (input) => {
      agents.set(input.sessionID, input.agent);
    },
    'tool.execute.before': async (input, output) => {
      const agent = agents.get(input.sessionID);
      if (typeof agent !== 'string' || !agent.startsWith(PREFIX)) return;
      const run = spawnSync(
        'node',
        [GUARD, agent.slice(PREFIX.length), 'opencode'],
        {
          // OpenCode's patch paths are relative to the project.
          cwd: directory,
          input: JSON.stringify({
            tool_name: input.tool,
            tool_input: output.args,
          }),
          encoding: 'utf8',
          timeout: 10000,
        },
      );
      // Exit 2 is a denial. Anything else, a missing guard or a crash
      // included, defers to OpenCode's own permissions: a guard that blocks
      // everything looks exactly like a broken agent.
      if (run.status !== 2) return;
      let reason = run.stderr;
      try {
        reason = JSON.parse(run.stdout).permissionDecisionReason || reason;
      } catch {
        // keep stderr
      }
      throw new Error(reason || 'Refused by the agent-roles guard.');
    },
  };
};
